INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210001, 101001, 'b89e3151-b364-5fa5-b619-f5bf7196de27', NULL, 'The ad label comparison is the strongest point here. We already accept that paid posts need a tag, so tagging the alteration in the image is not some radical new censorship. It is consistency.', 'strongly_agree', 8, '2026-09-23 16:29:12+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210003, 101004, '8bb4a54b-593d-5bed-a3f3-26ad61a571b9', NULL, 'The ring light question is real though. My sister is a photographer and she says retouching starts the moment you choose a lens. Any law will end up punishing amateurs while pros with better equipment sail through unlabeled.', 'disagree', 0, '2026-09-23 22:53:53+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210005, 101002, 'ed3f33e8-2ed5-52fe-9204-d44d3416eef0', NULL, 'The mascara example sold me. If the ad is literally demonstrating a product''s effect, faking the effect is fraud, full stop. That is already illegal in every other medium.', 'agree', 7, '2026-09-24 07:03:34+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210006, 101005, '84b4e3c8-f09e-5d8e-9c4f-2f651dc913bb', NULL, 'I see both sides. I want honesty in ads, but I also edit my own photos for fun and I would hate getting a legal threat over a color filter. Maybe limit it strictly to paid product claims and leave personal posts alone.', 'neutral', 1, '2026-09-23 15:18:02+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210008, 101003, 'be6993eb-cb2c-5d64-b4a9-3975597eaf9f', NULL, 'Level the playing field? Please. The big brands will just hire lawyers to certify their posts while small creators self-censor. Every simple disclosure rule lands hardest on the people with the least power.', 'strongly_disagree', 3, '2026-09-24 06:10:41+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210010, 101002, 'f84ec808-4956-5e7c-8849-bad1fe689484', NULL, 'Honest question for the fraud camp: who decides what counts as misleading? A whitening filter on a teeth-whitening ad is obvious, but most cases will be gray. I am not sure regulators will be better at this than the platforms'' own policies.', 'neutral', 2, '2026-09-24 05:28:34+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210011, 101007, '1bcf61ee-325a-573f-a2b9-0eee4134e83c', NULL, 'The leaded gasoline comparison is exactly right. Every industry facing a phaseout says it is impossible, and then the deadline arrives and they somehow manage. Deadlines work.', 'strongly_agree', 3, '2026-09-24 03:05:59+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210013, 101010, '68118fb8-cb09-5a77-83f8-e8bbb503e26b', NULL, 'The regressive tax point is the one the phaseout crowd never answers. When eggs spiked a few years ago, my food bank line doubled. Cheap protein is not an abstraction for poor families.', 'agree', 5, '2026-09-23 19:27:56+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210015, 101008, '9e2e50b6-c57a-59f8-ae45-d6c4cb898fbc', NULL, 'As a pharmacist, I have to push back: most antibiotic use driving resistance in hospitals comes from human overprescription, not farms. Blaming agriculture lets the medical system off the hook.', 'strongly_disagree', 7, '2026-09-23 13:22:07+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210017, 101011, '7afd7332-0657-5496-87f7-c916a5fe6d25', NULL, 'The offshoring argument is the strongest against case here, but it cuts both ways: if we regulate and others do not, should we just never regulate anything? That logic would have kept leaded gas forever.', 'neutral', 5, '2026-09-23 23:36:37+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210018, 101012, 'ffb4d8da-c5f4-5ec0-ba8f-b4c7b25af7b1', NULL, 'The contract grower point hit me. Those farmers are trapped by debt on barns they were told to build. A phaseout without a buyout is just cruelty to rural families.', 'agree', 3, '2026-09-24 01:36:51+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210019, 101009, 'd4f6b8cb-344c-53ee-a8f4-06d41cc3e7e9', NULL, 'Prop 12 is a weird example to celebrate. Pork prices in California rose and producers outside the state just built separate supply chains. It proved the market routes around rules, not that phaseouts work.', 'disagree', 5, '2026-09-23 19:47:49+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210021, 101013, 'bb906b2d-7809-5b09-9aaf-a2da6cf06ec9', NULL, 'The out-of-network anesthesiologist detail is what radicalized me. You can do everything right, pick an in-network hospital, and still get destroyed by one person you never chose. That is not a system, it is a trap.', 'strongly_agree', 7, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210023, 101016, '11001984-a81c-5f63-9d57-22119137a664', NULL, 'The tax point never gets a straight answer from the universal care side. Premiums are already a private tax I pay every month. Show me the honest math where my total goes down, not just slogans about the rich paying.', 'disagree', 3, '2026-09-24 13:37:13+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210025, 101014, '1c897af0-3464-50ce-99e1-c33a67bdd63e', NULL, 'The small business angle does not get enough attention. Tying health care to employment made sense during WWII wage controls. Eighty years later it is just a ball and chain on every company under 500 people.', 'agree', 4, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210026, 101017, 'b6fe015f-b990-5eda-8588-21fff49ca63e', NULL, 'I am torn on innovation. The US really does produce most new drugs, but a lot of that research starts with NIH grants, meaning taxpayers already fund the early science. Maybe the profits are privatized more than the risk.', 'neutral', 1, '2026-09-24 11:57:56+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210028, 101018, 'eec95a80-96c0-5f0c-a61d-0177b69ccc78', NULL, 'The VA point is devastating and nobody answers it. If the government cannot deliver timely care to 9 million veterans with a dedicated system, why would 330 million go better?', 'strongly_agree', 5, '2026-09-24 13:03:45+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210029, 101015, '4a837e03-4998-5dce-8d18-94c2f185217d', NULL, 'The money does not disappear, it moves to the IRS is the most honest sentence in this whole debate. Fine. I will pay the IRS if it means I never see another $90,000 cancer bill.', 'agree', 4, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210031, 101019, '59067b26-6ba1-5a41-8dab-c3e5c54f02f6', NULL, 'The car loan line is the whole argument. No bank cares that you usually make good money on Fridays. Wage stability is dignity, and tips cannot provide it.', 'strongly_agree', 0, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210033, 101022, '40b238fa-bd6d-5a06-a1a7-cb911ae9b424', NULL, 'As a server, the $68k number is real and the activists ignore it. I chose this job because busy nights pay like a skilled trade. A flat wage turns it into just another $20-an-hour job I would quit.', 'disagree', 7, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210035, 101020, '8bb4a54b-593d-5bed-a3f3-26ad61a571b9', NULL, 'California is the natural experiment that ends the debate. No tip credit, huge restaurant industry, still standing. If it worked at that scale, the doomsday predictions are just lobbying.', 'agree', 2, '2026-09-24 11:14:12+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210036, 101023, '3833d1ba-b691-5e7a-a568-e112c0ff84f1', NULL, 'Both sides assume all restaurants are the same. A busy steakhouse server and a diner waitress on a Tuesday live in different economies. Maybe the answer is raising the floor, not one national rule.', 'neutral', 7, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210038, 101021, 'ff19e6f5-eaa1-53fa-b890-94d583001c46', NULL, 'The back-of-house point is underrated. Cooks make the food and get none of the tip upside. Every kitchen staffing crisis traces back to servers making triple what the line makes.', 'agree', 5, '2026-09-24 12:19:02+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210039, 101024, '15533f7e-2945-540a-9857-a880198a8b7f', NULL, 'The service got worse claim is just vibes. Plenty of no-tip restaurants in New York and San Francisco have excellent service because they hire and train well. Good management beats tip incentives.', 'strongly_disagree', 7, '2026-09-24 13:19:45+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210041, 101025, 'a5e48176-d13e-56cd-9d5d-bf0677be0202', NULL, 'The escalation point is key. A first-time mistake should not be fatal, but the tenth mistake is a business model. Revenue-linked ceilings give regulators a ladder instead of a single hammer.', 'agree', 1, '2026-09-23 21:25:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210043, 101026, '8e153b48-6c1b-5bc0-b386-3a3d980570aa', NULL, 'As someone at a mid-size company, the compliance asymmetry is real. We spend a bigger share of revenue on privacy lawyers than any giant does. The fine structure just adds to the moat.', 'agree', 2, '2026-09-24 00:19:02+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210046, 101026, '84b4e3c8-f09e-5d8e-9c4f-2f651dc913bb', NULL, 'This gets it backwards. Without revenue linkage, fines are just a tax on being small. A $50 million flat fine kills a startup and amuses a giant. Revenue scaling is the only thing that makes punishment proportional.', 'strongly_disagree', 4, '2026-09-23 22:59:02+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210047, 101025, 'ba04f29b-87ce-5dce-84f9-f363fbd6b9d6', NULL, 'Fines do not change behavior nearly as much as people think. What changes behavior is personal liability and product bans. We are debating the size of the check while the underlying conduct continues.', 'disagree', 0, '2026-09-23 23:27:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210049, 101027, '6e27393e-259c-5273-b448-c8c4a01d49fb', NULL, 'The stolen diary line nails it. Deletion after the sale is theater. The data was already copied, resold, and merged a dozen times. Only money makes the harm concrete.', 'strongly_agree', 0, '2026-09-23 21:47:16+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210051, 101028, '5077d8a9-4b3e-5b88-b26e-4c1933504fb8', NULL, 'The weather app point is underappreciated. Blanket payout rules will just mean fewer small apps use location at all, and the giants who can afford compliance get stronger. Same story as always.', 'agree', 7, '2026-09-24 00:02:15+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210054, 101028, 'ca4fad3f-c547-5465-a567-d0804c7a4408', NULL, 'The tiny-check cynicism is exactly why payouts matter. Companies count on outrage fading. A hundred million small checks is still a hundred million reasons to stop.', 'strongly_disagree', 0, '2026-09-23 20:26:15+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210055, 101027, '7bfcb97a-8d40-50e6-898a-1c9ac6dbf2e4', NULL, 'Payment without fixing consent is just a subscription fee for abuse. Outlogic-style bans and deletion orders do more. Make the payout part of a ban, not a substitute for one.', 'disagree', 6, '2026-09-23 23:27:16+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210057, 101006, '36cfff0c-65b8-5120-a6ca-5a6638482165', NULL, 'The wrestling comparison nails it. My dad explained advertising tricks to me when I was ten and it stuck far better than any warning label could. Kids learn skepticism from people they trust, not from fine print under a photo.', 'agree', 6, '2026-09-24 01:38:51+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210058, 101006, '6b9fdf96-46bf-5cd0-8778-e9250866cd2b', NULL, 'Parents cannot be everywhere, and plenty of parents do not understand filters themselves. A simple altered-image tag gives kids a cue to pause, and it costs platforms almost nothing to add. We already label ads; labeling the alteration is the same idea.', 'disagree', 2, '2026-09-23 23:41:51+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210101, 101061, 'aa41ea2e-1856-5bfc-9547-d56c2937181a', NULL, 'The reentry angle convinced me. We spend billions on programs to reduce recidivism and then withhold one of the cheapest reintegration tools there is: a reason to feel like a citizen. A ballot costs the state almost nothing and tells someone their community still wants them in it.', 'agree', 6, '2026-09-23 19:42:59+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210103, 101062, 'e221802f-5357-518d-9f63-27b1c106c174', NULL, '1 in 19. Read that number twice. If any other policy locked out Black adults at that rate, we would call it what it is without hesitation. Automatic restoration does not fix policing or sentencing, but it stops the punishment from reproducing itself at the ballot box forever.', 'strongly_agree', 5, '2026-09-24 06:09:44+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210104, 101063, '0eef4bb1-4054-5855-a228-89a413d85030', NULL, 'The Maine and Vermont example is interesting, but those are two small states with unusual politics. I would want to see how prison voting works somewhere bigger and more politically charged before calling it reassuringly boring everywhere. Still, the burden of proof should be on the ban, not on the right.', 'neutral', 6, '2026-09-23 23:24:01+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210105, 101064, '7d76392f-0482-5082-ad2f-2b4b16a71d47', NULL, 'Restitution is the part everyone skips. A judge ordered that money to a victim, and waving it away because the offender is broke tells the victim their loss ranks below the offender''s convenience. Finish the sentence means finish the sentence, all of it.', 'agree', 4, '2026-09-24 07:01:03+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210107, 101065, '8e1ee936-3d62-57ca-973c-8572c907b23d', NULL, 'States'' rights is how we got literacy tests. Some rights are too fundamental to vary by zip code, and the franchise is at the top of that list. Let the states decide just means your citizenship is worth less in Montgomery than in Montpelier.', 'disagree', 0, '2026-09-23 19:17:38+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210108, 101066, '01016111-7c7d-5978-845d-676b6ce468a7', NULL, 'The 83% rearrest figure is the strongest point made on this page. I support restoration, but doing it automatically on release day ignores what we know about the first years after prison. Finish parole, stay clean for a defined period, then the ballot is waiting. That is a second chance with evidence.', 'agree', 5, '2026-09-24 05:23:19+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210110, 101065, '6069f4d9-134d-5568-b84d-113b4781f21f', NULL, 'The Constitution also left slavery to the states once. Federalism is a process argument, not a moral one, and it has been the shield for every voter suppression scheme in American history. Some questions are too big for let Mississippi decide.', 'strongly_disagree', 2, '2026-09-23 21:01:38+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210111, 101067, '8e1ee936-3d62-57ca-973c-8572c907b23d', NULL, 'Buy, borrow, die. Three words that explain why my effective tax rate is higher than a billionaire''s. The ProPublica figure should be printed on every pay stub in America. If you can live off loans against stock forever, you are earning income the code refuses to see.', 'strongly_agree', 4, '2026-09-23 21:38:08+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210113, 101068, 'd193d39a-90f5-5315-8985-4ddd7f60f9b2', NULL, 'The nurse''s point about overtime lands hard. The code tracks my hourly wages to the penny but treats a billionaire''s $500 million paper gain as if it does not exist. Unrealized does not mean imaginary: banks accept it as collateral every day.', 'agree', 5, '2026-09-24 01:18:47+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210114, 101070, '6069f4d9-134d-5568-b84d-113b4781f21f', NULL, 'Liquidity is a real problem, but the proposal has an answer: payment over several years, and it only touches households over $100 million. Let us argue about the actual proposal instead of a slippery-slope version of it.', 'disagree', 6, '2026-09-24 01:22:56+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210116, 101071, '1353e9e6-bed7-5215-8608-5bbd274806bb', NULL, 'The constitutional question is genuinely unresolved, and Moore deliberately left it open. I am sympathetic to the fairness argument, but building a major revenue program on a tax the Court might strike down is risky legislating. Congress should get a clearer ruling before betting the budget on it.', 'neutral', 5, '2026-09-23 15:01:45+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210117, 101072, '51ef71d8-14d6-5375-9c49-b8052358cdbb', NULL, 'France is the case study everyone ignores. They repealed the wealth tax after watching capital leave, and their revenue estimates never survived contact with appraisers and lawyers. Annual valuation of private businesses is a full-employment act for accountants, not a revenue plan.', 'agree', 0, '2026-09-23 20:12:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210118, 101069, '9d8ffff2-6857-5147-8090-f340fa759a75', NULL, 'Section 1256 covers liquid futures contracts with daily settlement prices, which is nothing like valuing a private company or an art collection once a year. The Netherlands comparison is worse: the Dutch system taxes an assumed return and their own supreme court just blew it up. These precedents prove less than they seem.', 'strongly_disagree', 7, '2026-09-23 23:35:47+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210121, 101073, '51ef71d8-14d6-5375-9c49-b8052358cdbb', NULL, 'The Gollum comparison is exactly right. Every effects breakthrough gets called the death of acting until an actor does something undeniable with it. Judge the performance on screen, not the pipeline behind it. The Academy''s rule is the only adult position here.', 'agree', 7, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210122, 101076, '9d8ffff2-6857-5147-8090-f340fa759a75', NULL, '118 days on a picket line, and now the industry wants to hand its highest honor to the technology people struck against? The strikes were about exactly this: human work being replaced and then celebrated. An Oscar for an AI film would spit on every actor still waiting for the phone to ring.', 'strongly_agree', 4, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210124, 101074, '5293caab-5d08-5c31-9778-fd2be406b076', NULL, 'As someone with a camera and no budget, this is personal. The industry gatekeeps through money, and AI is the first real crack in the gate. If awards stay closed to AI-assisted films, the message to kids like me is clear: the tools changed, but the velvet rope did not.', 'agree', 7, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210125, 101077, 'f80c2d72-01bd-55cd-8684-090bd4e11464', NULL, 'My art is in those training sets too, scraped without asking. Until there is a compensation system for the artists whose work taught these models, an Oscar for AI film is an award for laundering. Pay the training data, then we can talk about trophies.', 'strongly_agree', 4, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210127, 101075, '391df4bf-3997-5a4b-b74e-67f89cc9c301', NULL, 'Disclosure does not solve anything if voters cannot tell what the AI did. AI was used on a credits crawl tells me nothing about whether the performance I am judging is a person or a composite. Transparency theater is not the same as informed voting.', 'disagree', 3, '2026-09-24 12:27:51+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210128, 101078, 'fb8d24b5-9542-55f8-83a0-53212a53836f', NULL, 'Compute is the new studio system. Whoever has the biggest model and the most proprietary footage wins, which means Disney and Warner Bros., not the kid in the dorm room. Eligibility just moves the existing power imbalance onto shinier hardware.', 'agree', 4, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210131, 101079, '391df4bf-3997-5a4b-b74e-67f89cc9c301', NULL, 'Twenty minutes to refocus after one notification. Multiply that by a school day and it is a miracle anyone learns algebra at all. I am a teacher too, and the phone ban is the first policy in years that made my classroom feel like 2010 again, in the best way.', 'strongly_agree', 2, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210133, 101080, 'f1d74300-6314-519d-858e-21531de9e328', NULL, 'The school nurse sees what the statistics describe. Kids come in with stomach aches that are really dread about what is happening on their phones during lunch. Seven hours of enforced distance is the only break some of these kids get, and you can see the relief on their faces.', 'agree', 8, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210134, 101082, '486b6fdb-fea2-5050-bdda-391e1e4b1031', NULL, 'As a mom, the safety argument ends the debate for me. Lockdowns are real, office lines jam, and I want my daughter able to text me. No test score improvement is worth my child being unreachable in an emergency. Restrict use, fine, but never confiscate the lifeline.', 'strongly_agree', 3, '2026-09-24 12:38:04+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210136, 101081, 'a84309e6-d148-54ef-8191-634b14c46c3f', NULL, 'The pouch system clearly works where it is tried, and the cost is trivial. My hesitation is the emergency question: the office handles it assumes offices are staffed and responsive, which is not every school. I would want clear, published emergency protocols before supporting a mandate.', 'neutral', 5, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210137, 101083, '9636fdba-bd6d-5636-8afc-215db596d82c', NULL, 'The student is right that enforcement eats teaching time. My school''s ban turned every teacher into a phone cop and every period started with a negotiation. The kids who needed the ban most were the best at hiding the phone. We punished the compliant and trained the defiant.', 'agree', 3, '2026-09-24 12:26:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210138, 101084, '46d72e33-e266-58f6-98b4-f7426a76e81d', NULL, 'Digital literacy sounds great until you try teaching self-regulation to a 13-year-old whose apps are engineered by the best behavioral scientists on earth. We do not teach kids to manage cigarettes by handing them cigarettes. Sometimes removing the temptation is the lesson.', 'disagree', 6, '2026-09-24 11:00:40+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210141, 101085, 'f1d74300-6314-519d-858e-21531de9e328', NULL, '147 million people, and the executives kept their bonuses. That single fact radicalized me on this issue. A fine the company pays is just a business expense with better PR. Claw back the pay of the people who signed off on the security budget, and watch how fast the budget grows.', 'strongly_agree', 6, '2026-09-23 16:53:37+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
